import { request, requestOrNull, seg, Page, requestFile, ExportRequest } from './apiSupport';
import { ProductDTO } from './ProductDTO';
import { ProductKeyDTO } from './ProductKeyDTO';
import { ProductSrchDTO } from './ProductSrchDTO';

/**
 * REST client for Product.
 *
 * Calls the endpoints ProductController exposes. Generated from the same model the
 * server is, so a change to the DSL shows up here as a type error rather than
 * at runtime.
 *
 * Generated by ElastiCORE. Do not edit outside the ElastiCORE guidelines.
 */
const BASE = '/api/crm/product';

/** Registers a new Product. */
export async function create(input: ProductDTO, init?: RequestInit): Promise<ProductDTO> {
    return request<ProductDTO>('POST', BASE, input, init);
}

/** The Product with this identifier, or null when there is none. */
export async function findById(productId: number, init?: RequestInit): Promise<ProductDTO | null> {
    return requestOrNull<ProductDTO>('GET', BASE + '/' + seg(productId), init);
}

/** Every Product matching the condition. */
export async function search(condition: ProductSrchDTO, init?: RequestInit): Promise<Page<ProductDTO>> {
    return request<Page<ProductDTO>>('POST', BASE + '/search', condition, init);
}

/** Updates an existing Product. */
export async function update(input: ProductDTO, init?: RequestInit): Promise<ProductDTO> {
    return request<ProductDTO>('PUT', BASE, input, init);
}

/** Updates several in one transaction; none are applied if any fails. */
export async function batchUpdate(inputs: ProductDTO[], init?: RequestInit): Promise<void> {
    return request<void>('PUT', BASE + '/batch', inputs, init);
}

/** Deletes each key, answering for each whether it was there. */
export async function deleteMany(keys: ProductKeyDTO[], init?: RequestInit): Promise<boolean[]> {
    return request<boolean[]>('POST', BASE + '/delete', keys, init);
}

/** Deletes the Product with this identifier. */
export async function deleteById(productId: number, init?: RequestInit): Promise<boolean> {
    return request<boolean>('DELETE', BASE + '/' + seg(productId), undefined, init);
}

/** The rows the search finds as a file: CSV, or an .xlsx workbook (format: 'xlsx'). */
export async function exportProduct(body: ExportRequest<ProductSrchDTO>, init?: RequestInit): Promise<Blob> {
    return requestFile('POST', BASE + '/export', body, init);
}

